//! Actual host success/failure routes through the SAME production embedding
//! factory; real OS deletion after marker, no replay override or injected status.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{input_snapshot::{SnapshotProvider,RecordingInputs},policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,BuildOutcome,Command},runner_host::BuildHost};
use dm_preprocess::{SourceProvider,OriginalRawReadOutcome as Outcome,OriginalRawOpenDecision as Decision,source_arena_credit::read_original_source_open_using};
use std::{path::{Path,PathBuf},io};
fn put(root:&Path,relative:&str,text:impl AsRef<[u8]>){let p=root.join(relative);std::fs::create_dir_all(p.parent().unwrap()).unwrap();std::fs::write(p,text).unwrap()}
fn fixture(label:&str)->PathBuf{let root=scratch::dir(label);put(&root,"deepquarry.dme","#include \"code/probe.dm\"\n");put(&root,"code/probe.dm","/obj/probe\n    var/value\n/obj/probe/ui_data()\n    return list(value)\n");put(&root,"code/_generated/reads.dm","// genuine stale file\n");put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));root}
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual PrepareQuery")};let mut r=*request;r.no_cache=true;r.exact_inputs=true;r.progress_enabled=false;r.workers=1;r.timeout_seconds=Some(60);r.engine_template=None;r.bootstrap_catalog=false;r.cache_root=Some(root.join("cache"));r.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_path_buf(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::DerivedReads],..Default::default()});r}
#[path="support/actual_original_provider.rs"]mod actual_provider;
#[test]fn actual_attempt_complete_uses_existing_current_report_and_wrong_role_refuses_before_callback(){let root=fixture("derived-attempt-complete");let req=request(&root);let mut host=BuildHost::default();let result=host.with_derived_attempt_report(req.clone(),|data,_|Ok(data.sites().len())).unwrap();assert!(matches!(result.preparation,Ok(BuildOutcome::QueryPrepared{retained:true,..})));assert!(result.report.unwrap().is_ok());let mut wrong=req;wrong.policy_inputs.as_mut().unwrap().workspace_auxiliary=vec![Q::SemReads];let mut called=false;assert!(host.with_derived_attempt_report(wrong,|_,_|{called=true;Ok(())}).is_err());assert!(!called)}
#[test]fn actual_failed_second_reader_reports_once_without_successful_preparation_or_current_cache(){let root=fixture("derived-attempt-failed-root");let req=request(&root);let mut host=BuildHost::default();let mut calls=0;for _ in 0..2{put(&root,"deepquarry.dme","#include \"code/probe.dm\"\n");let provider=actual_provider::source(true);let result=host.with_derived_attempt_report_from(req.clone(),&provider,|data,_|{calls+=1;assert!(data.sites().iter().any(|s|s.rule=="untracked_ui_read"),"sem-unavailable cannot invent never-written exemption");assert!(data.generated_is_stale());Ok(data.sites().to_vec())}).unwrap();let error=result.preparation.unwrap_err();assert_eq!(error.downcast_ref::<io::Error>().map(io::Error::kind),Some(io::ErrorKind::NotFound),"actual preparation source error must remain first");assert!(!result.report.unwrap().unwrap().is_empty());assert!(host.declaration_retention_stats().is_none(),"failed report is not a declaration/source cache grant");}assert_eq!(calls,2,"each real failed attempt owns its own one-shot report; no cached success")}
#[test]fn actual_source_error_survives_later_report_callback_io(){let root=fixture("derived-attempt-first-error");let req=request(&root);let mut host=BuildHost::default();let provider=actual_provider::source(true);let result=host.with_derived_attempt_report_from(req,&provider,|_,_|Err::<(),_>(io::Error::from_raw_os_error(1450))).unwrap();let first=result.preparation.unwrap_err();assert_eq!(first.downcast_ref::<io::Error>().map(io::Error::kind),Some(io::ErrorKind::NotFound));assert_eq!(result.report.unwrap().unwrap_err().raw_os_error(),Some(1450),"later report IO stays separate rather than replacing source failure")}
